// Field presentation state. Every input may be unconnected, so guard everything.
const rawError = Inputs.Error;
const rawHelper = Inputs.HelperText;
const error = typeof rawError === 'string' ? rawError.trim() : '';
const helper = typeof rawHelper === 'string' ? rawHelper : '';
const hasError = error.length > 0;

Outputs.HasError = hasError;
Outputs.BorderColor = hasError ? 'var(--destructive)' : 'var(--border)';
Outputs.Message = hasError ? error : helper;
Outputs.MessageColor = hasError ? 'var(--destructive)' : 'var(--muted-foreground)';
Outputs.MessageVisible = hasError || helper.length > 0;
Outputs.Enabled = Inputs.Disabled === true ? false : true;

