// Turn the underlying DOM input into a native date input.
// Guarded: if anything is missing the field degrades to a plain
// text input with a YYYY-MM-DD placeholder.
Script.Signals.DidMount = () => {
    const host = Script.Inputs.TextInput;
    if (!host || typeof host.getDOMElement !== 'function') return;
    const el = host.getDOMElement();
    if (!el || typeof el.querySelector !== 'function') return;
    const input = el.querySelector('input');
    if (input) input.type = 'date';
};

